37	    /** City -> region -> inclusive 4-digit postcode range {low, high}. */
38	    private static final Map<String, int[]> CITY_RANGE = Map.of(
39	        "Sydney", new int[] {2000, 2099},
40	        "Melbourne", new int[] {3000, 3099},
41	        "Brisbane", new int[] {4000, 4099});
42	
43	    @InitBinder
44	    void registerOwnerPostcodeValidator(WebDataBinder binder) {
45	        binder.addValidators(this);
46	    }
47	
48	    @Override
49	    public boolean supports(Class<?> clazz) {
50	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
51	    }
52	
53	    @Override
54	    public void validate(Object target, Errors errors) {
55	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
56	        String postcode = owner.getPostcode();
57	        int[] range = CITY_RANGE.get(owner.getCity());
58	        if (postcode == null || range == null || !postcode.matches("[0-9]{4}")) {
59	            return;
