26	/**
27	 * Rejects creating an owner when the owner's city already contains 50 or more owners, comparing
28	 * the city case-insensitively with runs of whitespace collapsed.
29	 */
30	@Aspect
31	@Component
32	public class OwnerCityCapacityAdvice {
33	
34	    private static final int CITY_CAPACITY = 50;
35	
36	    private final ClinicService clinicService;
37	
38	    public OwnerCityCapacityAdvice(ClinicService clinicService) {
39	        this.clinicService = clinicService;
40	    }
41	
42	    @Before("execution(* org.springframework.samples.petclinic.rest.controller.v1.OwnerRestControllerV1.addOwner(..)) && args(fields)")
43	    public void rejectFullCity(OwnerFieldsDto fields) {
44	        String city = normalize(fields.getCity());
45	        if (city == null) {
46	            return;
47	        }
48	        long owners = clinicService.findAllOwners().stream()
49	            .filter(existing -> city.equals(normalize(existing.getCity())))
50	            .count();
51	        if (owners >= CITY_CAPACITY) {
52	            throw new ResponseStatusException(HttpStatus.CONFLICT, "This city already has the maximum number of owners");
53	        }
54	    }
55	
56	    private static String normalize(String value) {
57	        return value == null ? null : value.strip().replaceAll("\\s+", " ").toLowerCase();
58	    }
59	}
