17	
18	import java.util.Map;
19	import java.util.concurrent.ConcurrentHashMap;
20	
21	import org.aspectj.lang.ProceedingJoinPoint;
22	import org.aspectj.lang.annotation.Around;
23	import org.aspectj.lang.annotation.Aspect;
24	import org.springframework.core.Ordered;
25	import org.springframework.core.annotation.Order;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.stereotype.Component;
28	import org.springframework.web.context.request.RequestContextHolder;
29	import org.springframework.web.context.request.ServletRequestAttributes;
30	
31	/**
32	 * Makes owner creation idempotent per {@code Idempotency-Key} request header. The first create
33	 * seen for a key is remembered along with its fully-derived response; a later create repeating
34	 * that key returns the originally created owner with {@code 200 OK} instead of creating a
35	 * duplicate. Highest precedence makes this wrap every other owner-create advice, so a repeat
36	 * short-circuits before any duplicate check runs.
37	 */
38	@Aspect
39	@Component
40	@Order(Ordered.HIGHEST_PRECEDENCE)
41	public class OwnerIdempotencyAdvice {
42	
43	    private static final String HEADER = "Idempotency-Key";
44	
45	    private final Map<String, Object> seen = new ConcurrentHashMap<>();
46	
47	    @Around("execution(* org.springframework.samples.petclinic.rest.controller.v1.OwnerRestControllerV1.addOwner(..))")
48	    public Object idempotentCreate(ProceedingJoinPoint pjp) throws Throwable {
49	        String key = idempotencyKey();
50	        if (key == null) {
51	            return pjp.proceed();
52	        }
53	        Object cached = seen.get(key);
54	        if (cached != null) {
55	            return ResponseEntity.ok(((ResponseEntity<?>) cached).getBody());
56	        }
57	        Object response = pjp.proceed();
58	        seen.put(key, response);
59	        return response;
60	    }
61	
62	    private String idempotencyKey() {
63	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs) {
64	            String key = attrs.getRequest().getHeader(HEADER);
65	            if (key != null && !key.isBlank()) {
66	                return key;
67	            }
68	        }
69	        return null;
70	    }
71	}
