21	/**
22	 * Applies the structured address form to an owner payload. Normalizes 'addressLine1', 'addressLine2'
23	 * and the flat 'address' with {@link AddressNormalizer}, then composes the flat 'address' from the
24	 * structured fields when an 'addressLine1' is supplied (the normalized line 1, plus a single space
25	 * and the normalized line 2 when present), and otherwise keeps the normalized flat 'address'. The
26	 * composed value is written back to the payload and returned so the caller can validate its presence.
27	 */
28	final class StructuredAddress {
29	
30	    private StructuredAddress() {
31	    }
32	
33	    static String apply(OwnerFieldsDto owner) {
34	        String line1 = AddressNormalizer.normalize(owner.getAddressLine1());
35	        String line2 = AddressNormalizer.normalize(owner.getAddressLine2());
36	        owner.setAddressLine1(line1);
37	        owner.setAddressLine2(line2);
38	        String address;
39	        if (line1 == null || line1.isBlank()) {
40	            address = AddressNormalizer.normalize(owner.getAddress());
41	        } else {
42	            address = line2 == null || line2.isBlank() ? line1 : line1 + " " + line2;
43	        }
44	        owner.setAddress(address);
45	        return address;
46	    }
47	}
