18	import java.time.DayOfWeek;
19	import java.time.LocalDate;
20	import java.util.Set;
21	
22	/**
23	 * Rolls a date onto a business day: a Saturday, Sunday or listed public holiday is moved forward
24	 * to the next non-holiday weekday, any other weekday is returned unchanged.
25	 */
26	public final class BusinessDay {
27	
28	    /** Fixed public holidays skipped by the business-day roll. */
29	    private static final Set<LocalDate> HOLIDAYS = Set.of(
30	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
31	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
32	
33	    private BusinessDay() {
34	    }
35	
36	    public static LocalDate onOrNextBusinessDay(LocalDate date) {
37	        while (!isBusinessDay(date)) {
38	            date = date.plusDays(1);
39	        }
40	        return date;
41	    }
42	
43	    private static boolean isBusinessDay(LocalDate date) {
44	        DayOfWeek day = date.getDayOfWeek();
45	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !HOLIDAYS.contains(date);
46	    }
47	}
